sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    var fields = ['admission', 'appointment', 'invoice', 'lab_test_result'];

    // If subcategory is empty (new record or category reset), hide all and clear
    if (!newValue) {
        for (var i = 0; i < fields.length; i++) {
            g_form.setMandatory(fields[i], false);
            g_form.setDisplay(fields[i], false);
            if (!isLoading) {
                g_form.setValue(fields[i], '');
            }
        }
        return;
    }

    var subcategory = String(newValue);

    // Reset all fields to hidden and non-mandatory before evaluating
    for (var j = 0; j < fields.length; j++) {
        g_form.setMandatory(fields[j], false);
        g_form.setDisplay(fields[j], false);
    }

    // 1. Mandatory Single Admission
    // Facilities: AC (131), Plumbing (132), Electrical (133)
    // Hygiene: Room cleaning (102), Linen (103)
    // Food: Meal delivery (111), Incorrect diet (112)
    // General: Clinical care (145)
    var mandatoryAdmissionSubcats = ['131', '132', '133', '102', '103', '111', '112', '145'];
    if (mandatoryAdmissionSubcats.indexOf(subcategory) > -1) {
        g_form.setDisplay('admission', true);
        g_form.setMandatory('admission', true);
        return;
    }

    // 2. Shared / Dual Reference: Admission + Appointment
    // Facilities: Lift (134), Parking (135) [Optional either/neither]
    // Hygiene: Washroom (101), Bio-waste (104), Sanitizer (105) [Optional either/neither]
    // Staff Behavior: Doctor Communication (121) [Mandatory either]
    // Staff Behavior: Security / Attendant (124) [Optional either/neither]
    // Staff Behavior: Lack of Empathy (125) [Mandatory either]
    // General: Other feedback (146) [Optional either/neither]
    var sharedSubcats = ['134', '135', '101', '104', '105', '121', '124', '125', '146'];
    if (sharedSubcats.indexOf(subcategory) > -1) {
        g_form.setDisplay('admission', true);
        g_form.setDisplay('appointment', true);
        return;
    }

    // 3. Admission Only (Optional)
    // Staff Behavior: Nursing Staff Delay / Behavior (122)
    // Food: Food quality (113)
    if (subcategory === '122' || subcategory === '113') {
        g_form.setDisplay('admission', true);
        return;
    }

    // 4. Staff Behavior: Billing / Admin Staff Misconduct (123)
    // Displays Admission + Invoice [Mandatory either]
    if (subcategory === '123') {
        g_form.setDisplay('admission', true);
        g_form.setDisplay('invoice', true);
        return;
    }

    // 5. Appointment
    // General: Appointment / Scheduling Issue (142) -> Mandatory
    // General: Waiting time (141) -> Optional
    if (subcategory === '142') {
        g_form.setDisplay('appointment', true);
        g_form.setMandatory('appointment', true);
        return;
    }
    if (subcategory === '141') {
        g_form.setDisplay('appointment', true);
        return;
    }

    // 6. Lab Test Result
    // General: Laboratory / Diagnostic Report Delay (143) -> Mandatory
    if (subcategory === '143') {
        g_form.setDisplay('lab_test_result', true);
        g_form.setMandatory('lab_test_result', true);
        return;
    }

    // 7. Invoice
    // General: Billing & Insurance / TPA Query (144) -> Mandatory
    if (subcategory === '144') {
        g_form.setDisplay('invoice', true);
        g_form.setMandatory('invoice', true);
        return;
    }
}
